//! `http-state`'s `tests/data/dates/`: cookie-date parsing cases, as a
//! table of (input octets, expected date or failure).
//!
//! Each file is a JSON array of `{"test": ..., "expected": ...}` objects,
//! where `expected` is a date formatted as `Mon, 10 Dec 2007 17:02:24 GMT`
//! or `null` (failure). `bsd-examples.json` begins with a license header
//! of `//` comment lines, which are removed before parsing. The weekday
//! in `expected` is kept: the test checks it against the parsed date.

use std::fmt::Write as _;
use std::path::Path;

use serde_json::Value;

/// The files vendored for this suite (besides LICENSE.md and SOURCE.md).
pub const FILES: &[&str] = &["examples.json", "bsd-examples.json"];

const DAYS: [&str; 7] = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const MONTHS: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

struct Case {
    file: &'static str,
    index: usize,
    input: Vec<u8>,
    /// (year, month, day, hour, minute, second, weekday with Monday 0).
    expected: Option<(u32, u32, u32, u32, u32, u32, u32)>,
}

fn parse_expected(file: &str, s: &str) -> Result<(u32, u32, u32, u32, u32, u32, u32), String> {
    let bad = || format!("{file}: cannot read expected date {s:?}");
    let parts: Vec<&str> = s.split([' ', ',', ':']).filter(|p| !p.is_empty()).collect();
    let [wd, day, mon, year, h, m, sec, gmt] = parts.as_slice() else {
        return Err(bad());
    };
    if *gmt != "GMT" {
        return Err(bad());
    }
    let num = |t: &str| t.parse::<u32>().map_err(|_| bad());
    let weekday = DAYS.iter().position(|d| d == wd).ok_or_else(bad)?;
    let month = MONTHS.iter().position(|d| d == mon).ok_or_else(bad)?;
    Ok((
        num(year)?,
        u32::try_from(month).map_err(|_| bad())?.saturating_add(1),
        num(day)?,
        num(h)?,
        num(m)?,
        num(sec)?,
        u32::try_from(weekday).map_err(|_| bad())?,
    ))
}

pub fn convert(dir: &Path) -> Result<String, String> {
    let mut cases = Vec::new();
    for file in FILES {
        let path = dir.join(file);
        let text = std::fs::read_to_string(&path).map_err(|e| format!("{file}: {e}"))?;
        let json: String = text
            .lines()
            .filter(|l| !l.trim_start().starts_with("//"))
            .collect::<Vec<_>>()
            .join("\n");
        let rows: Value = serde_json::from_str(&json).map_err(|e| format!("{file}: {e}"))?;
        let rows = rows
            .as_array()
            .ok_or_else(|| format!("{file}: not a JSON array"))?;
        let name: &'static str = if *file == "examples.json" {
            "examples"
        } else {
            "bsd-examples"
        };
        for (index, row) in rows.iter().enumerate() {
            let test = row
                .get("test")
                .and_then(Value::as_str)
                .ok_or_else(|| format!("{file}[{index}]: no string \"test\""))?;
            let expected = match row.get("expected") {
                Some(Value::Null) => None,
                Some(Value::String(s)) => Some(parse_expected(file, s)?),
                _ => return Err(format!("{file}[{index}]: bad \"expected\"")),
            };
            cases.push(Case {
                file: name,
                index,
                input: test.as_bytes().to_vec(),
                expected,
            });
        }
    }
    let mut out = String::new();
    out.push_str("// @generated by `cargo xtask testdata` from tests/data/http-state-dates/.\n");
    out.push_str("// Do not edit: `cargo xtask verify` fails if this differs from what the\n");
    out.push_str("// converter (xtask/src/testdata/http_state_dates.rs) produces.\n");
    out.push_str("// Source, commit and license: tests/data/http-state-dates/SOURCE.md.\n");
    out.push_str("const DATES: &[Case] = &[\n");
    for c in &cases {
        let input: Vec<String> = c.input.iter().map(|b| format!("0x{b:02X}")).collect();
        let expected = match c.expected {
            None => "None".to_owned(),
            Some((y, mo, d, h, mi, s, wd)) => format!("Some(({y}, {mo}, {d}, {h}, {mi}, {s}, {wd}))"),
        };
        writeln!(
            out,
            "    Case {{ file: {:?}, index: {}, input: &[{}], expected: {expected} }},",
            c.file,
            c.index,
            input.join(", ")
        )
        .map_err(|e| e.to_string())?;
    }
    out.push_str("];\n");
    Ok(out)
}
